import{_ as t,o as n,c as s,a2 as a}from"./chunks/framework.Bg-Zxr5O.js";const d=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"manual-en/Statistical-Functions.md","filePath":"manual-en/Statistical-Functions.md","lastUpdated":1785684581000}'),i={name:"manual-en/Statistical-Functions.md"};function o(r,e,u,m,c,l){return n(),s("div",null,[...e[0]||(e[0]=[a('<h4 id="_7-7-6-statistical-functions" tabindex="-1">7.7.6 Statistical Functions <a class="header-anchor" href="#_7-7-6-statistical-functions" aria-label="Permalink to &quot;7.7.6 Statistical Functions&quot;">​</a></h4><p>Statistical functions compute descriptive statistics on a list of values. Some statistics can be computed on numeric or string values; other can only be computed on numeric values. Their results have the same type as their arguments. The current case’s weighting factor (see <a href="./WEIGHT">WEIGHT</a>) has no effect on statistical functions.</p><p>These functions’ argument lists may include entire ranges of variables using the <code>var1 TO var2</code> syntax.</p><p>Unlike most functions, statistical functions can return non-missing values even when some of their arguments are missing. Most statistical functions, by default, require only 1 non-missing value to have a non-missing return, but <code>CFVAR</code>, <code>SD</code>, and <code>VARIANCE</code> require 2. These defaults can be increased (but not decreased) by appending a dot and the minimum number of valid arguments to the function name. For example, <code>MEAN.3(X, Y, Z)</code> would only return non-missing if all of ‘X’, ‘Y’, and ‘Z’ were valid.</p><p>Function: __<strong>CFVAR</strong> <em>( number, number[, …])</em></p><p>Results in the coefficient of variation of the values of number. (The coefficient of variation is the standard deviation divided by the mean.)</p><p>Function: __<strong>MAX</strong> <em>( value, value[, …])</em></p><p>Results in the value of the greatest value. The values may be numeric or string.</p><p>Function: __<strong>MEAN</strong> <em>( number, number[, …])</em></p><p>Results in the mean of the values of number.</p><p>Function: __<strong>MEDIAN</strong> <em>( number, number[, …])</em></p><p>Results in the median of the values of number. Given an even number of nonmissing arguments, yields the mean of the two middle values.</p><p>Function: __<strong>MIN</strong> <em>( number, number[, …])</em></p><p>Results in the value of the least value. The values may be numeric or string.</p><p>Function: __<strong>SD</strong> <em>( number, number[, …])</em></p><p>Results in the standard deviation of the values of number.</p><p>Function: __<strong>SUM</strong> <em>( number, number[, …])</em></p><p>Results in the sum of the values of number.</p><p>Function: __<strong>VARIANCE</strong> <em>( number, number[, …])</em></p><p>Results in the variance of the values of number.</p>',20)])])}const f=t(i,[["render",o]]);export{d as __pageData,f as default};
